interface.definition:
#"SYSTEM_SYSRULES_ButtonArrayLayout"(
  buttons: {
    #"SYSTEM_SYSRULES_buttonWidget_v1"(
      style: "LINK",
      size: "SMALL",
      label: "<<",
      disabled: ri!startIndex = 1,
      saveInto: {
        a!save(ri!startIndex, 1),
        a!save(ri!selectedIds, null)
      }
    ),
    #"SYSTEM_SYSRULES_buttonWidget_v1"(
      style: "LINK",
      size: "SMALL",
      label: "<",
      disabled: ri!startIndex = 1,
      saveInto: {
        a!save(
          ri!startIndex,
          (ri!startIndex - ri!batchSize)
        ),
        a!save(ri!selectedIds, null)
      }
    ),
    #"SYSTEM_SYSRULES_buttonWidget_v1"(
      style: "LINK",
      size: "SMALL",
      label: concat(
        ri!startIndex,
        " - ",
        (ri!startIndex + ri!batchSize - 1),
        " De ",
        ri!totalCount
      ),
      disabled: true()
    ),
    #"SYSTEM_SYSRULES_buttonWidget_v1"(
      style: "LINK",
      size: "SMALL",
      label: ">",
      disabled: or(
        ri!currentPage = ri!totalPages,
        ri!totalCount = 0
      ),
      saveInto: {
        a!save(
          ri!startIndex,
          (ri!startIndex + ri!batchSize)
        ),
        a!save(ri!selectedIds, null)
      }
    ),
    #"SYSTEM_SYSRULES_buttonWidget_v1"(
      style: "LINK",
      size: "SMALL",
      label: ">>",
      disabled: or(
        ri!currentPage = ri!totalPages,
        ri!totalCount = 0
      ),
      saveInto: {
        a!save(
          ri!startIndex,
          (
            (
              ri!batchSize * tointeger(
                ceiling(ri!totalCount / ri!batchSize)
              )
            ) - ri!batchSize + 1
          )
        ),
        a!save(ri!selectedIds, null)
      }
    )
  },
  align: "CENTER",
  showWhen: ri!totalCount > 0
)
